#!/usr/bin/env bash
# СУДИТ: hooks/backlog-open-write-guard.sh
# probe_D1134 — раскол блока пункта судится переездом его строк, а не формой правки. Красная (1), пока проходят: перенос
# СУЩЕСТВУЮЩЕГО пункта внутрь чужого блока (Write) и вставка нового внутрь блока вместе с правкой ранней строки этого же
# пункта (MultiEdit) — признак D1122 требовал нового пункта и нетронутого начала блока (четвёртый скептик, M2, M3).
# Контроль — новый пункт внутрь блока отбит; отрицательный контроль — закрытие пункта и новый пункт в конце одной
# правкой проходят (шаблонная строка «Проверки возврата» переездом не считается). Рамка — 2.
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
HOOK="$R/hooks/backlog-open-write-guard.sh"; [ -f "$HOOK" ] && command -v jq >/dev/null 2>&1 || exit 2
T=$(mktemp -d "${TMPDIR:-/tmp}/probe-D1134.XXXXXX") || exit 2
BL="$T/BACKLOG.md"; ST="$T/state"; mkdir -p "$ST"
RET='  **Проверка возврата:** решение — пункт описывает наличный дефект, возврат наступает, когда за него берутся.'
base() { printf '%s\n' '# BACKLOG' '' '- ☑ **D10** закрытый' '  **Корень.** R6 — два состояния.' '  **Проверка.** `true` → 0' \
    '  **Зелёная сторона.** нога D10.' '  **Показание.** «Проверка» 0 (до — 1).' '' \
    '- ☑ **D12** другой закрытый' '  **Корень.** R6 — два состояния.' '  **Проверка.** `true` → 0' '  **Показание.** 0.' '' \
    '- ◐ **D13** открытый' '  **Корень.** R6 — два состояния.' '  **Проверка.** `false` → 0' "$RET" > "$BL"; }
run() { CLAUDSOUL_ROOT="$R" STATE_DIR="$ST" bash "$HOOK" 2>/dev/null | jq -r '.hookSpecificOutput.permissionDecision // "allow"' 2>/dev/null; }
NEW=$'- ☐ **D11** новый\n  **Повод.** `x.sh:1` ломается.\n  **Корень.** R6 — два состояния.\n  **Проверка.** `false` → 0'
ed() { jq -cn --arg f "$BL" --arg o "$1" --arg n "$2" '{session_id:"p",tool_name:"Edit",tool_input:{file_path:$f,old_string:$o,new_string:$n}}' | run; }
base
[ "$(ed '  **Зелёная сторона.** нога D10.' "  **Зелёная сторона.** нога D10.

$NEW")" = deny ] || exit 2
# Отрицательный контроль: D13 закрыт (проверка возврата → показание), D11 — в конце файла со своей проверкой возврата.
neg=$(ed "  **Проверка.** \`false\` → 0
$RET" "  **Проверка.** \`false\` → 0
  **Показание.** закрыт.

$NEW
$RET")
[ "${neg:-allow}" = allow ] || { echo "закрытие пункта и новый пункт в конце одной правкой отбиты" >&2; exit 2; }
D12=$'- ☑ **D12** другой закрытый\n  **Корень.** R6 — два состояния.\n  **Проверка.** `true` → 0\n  **Показание.** 0.'
newc=$(printf '%s\n' '# BACKLOG' '' '- ☑ **D10** закрытый' '  **Корень.** R6 — два состояния.' '  **Проверка.** `true` → 0' "$D12" \
    '  **Зелёная сторона.** нога D10.' '  **Показание.** «Проверка» 0 (до — 1).' '' '- ◐ **D13** открытый' '  **Корень.** R6 — два состояния.' '  **Проверка.** `false` → 0' "$RET")
r2=$(jq -cn --arg f "$BL" --arg c "$newc" '{session_id:"p",tool_name:"Write",tool_input:{file_path:$f,content:$c}}' | run)
[ "$r2" = deny ] || { echo "перенос существующего пункта внутрь чужого блока прошёл" >&2; exit 1; }
r3=$(jq -cn --arg f "$BL" --arg o1 '  **Корень.** R6 — два состояния.
  **Проверка.** `true` → 0
  **Зелёная' --arg n1 '  **Корень.** R6 — два состояния (уточнено).
  **Проверка.** `true` → 0
  **Зелёная' --arg o2 '  **Зелёная сторона.** нога D10.' --arg n2 "  **Зелёная сторона.** нога D10.

$NEW" '{session_id:"p",tool_name:"MultiEdit",tool_input:{file_path:$f,edits:[{old_string:$o1,new_string:$n1},{old_string:$o2,new_string:$n2}]}}' | run)
[ "$r3" = deny ] || { echo "вставка внутрь блока с правкой его ранней строки прошла" >&2; exit 1; }
echo "раскол — по переезду строк"
exit 0
